	private static void handle(HttpExchange exchange, SailRepository repository, boolean capability,
			AtomicReference<Throwable> failure) throws IOException {
		try {
			if (exchange.getRequestURI().getPath().equals("/protocol")) {
				respond(exchange, 200, "text/plain", Protocol.VERSION.getBytes(StandardCharsets.UTF_8));
				return;
			}
			var request = new MockHttpServletRequest(exchange.getRequestMethod(), exchange.getRequestURI().getPath());
			exchange.getRequestHeaders().forEach((name, values) -> {
				if (capability || !name.equalsIgnoreCase(BNodeOriginTransport.HEADER)) {
					values.forEach(value -> request.addHeader(name, value));
				}
			});
			request.setAttribute("repository", repository);
			var response = new MockHttpServletResponse();
			Map<String, String> parameters = parameters(exchange.getRequestURI().getRawQuery());
			if (exchange.getRequestMethod().equals("POST")) {
				parameters.putAll(
						parameters(new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8)));
			}
			Map<String, Object> model = new HashMap<>();
			model.put(QueryResultView.HEADERS_ONLY, false);
			if (exchange.getRequestURI().getPath().endsWith("/statements")) {
				model.put(ExportStatementsView.FACTORY_KEY, new BinaryRDFWriterFactory());
				model.put(ExportStatementsView.USE_INFERENCING_KEY, true);
				model.put(ExportStatementsView.CONTEXTS_KEY, new Resource[0]);
				ExportStatementsView.getInstance().render(model, request, response);
			} else {
				var connection = repository.getConnection();
				model.put(QueryResultView.CONNECTION_KEY, connection);
				var query = connection.prepareQuery(QueryLanguage.SPARQL, parameters.get("query"));
				if (query instanceof GraphQuery graphQuery) {
					model.put(QueryResultView.FACTORY_KEY, new BinaryRDFWriterFactory());
					model.put(QueryResultView.QUERY_RESULT_KEY, graphQuery.evaluate());
					GraphQueryResultView.getInstance().render(model, request, response);
				} else {
					model.put(QueryResultView.FACTORY_KEY, new BinaryQueryResultWriterFactory());
					model.put(QueryResultView.QUERY_RESULT_KEY, ((TupleQuery) query).evaluate());
					TupleQueryResultView.getInstance().render(model, request, response);
				}
			}
			if (response.getHeader(BNodeOriginTransport.HEADER) != null) {
				exchange.getResponseHeaders()
						.set(BNodeOriginTransport.HEADER, response.getHeader(BNodeOriginTransport.HEADER));
			}
			respond(exchange, response.getStatus(), response.getContentType(), response.getContentAsByteArray());
		} catch (Throwable problem) {
			failure.compareAndSet(null, problem);
			respond(exchange, 500, "text/plain", problem.toString().getBytes(StandardCharsets.UTF_8));
		} finally {
			exchange.close();
		}
	}

	private static Map<String, String> parameters(String text) {
		Map<String, String> result = new HashMap<>();
		if (text != null && !text.isEmpty()) {
			for (String pair : text.split("&")) {
				String[] parts = pair.split("=", 2);
				result.put(URLDecoder.decode(parts[0], StandardCharsets.UTF_8),
						parts.length > 1 ? URLDecoder.decode(parts[1], StandardCharsets.UTF_8) : "");
			}
		}
		return result;
	}

	private static void respond(HttpExchange exchange, int status, String contentType, byte[] bytes)
			throws IOException {
		exchange.getResponseHeaders().set("Content-Type", contentType);
		exchange.sendResponseHeaders(status, bytes.length);
		exchange.getResponseBody().write(bytes);
	}
